```yaml
name: Weekly Repo Status

on:
  schedule:
    # Runs every Sunday at 00:00 UTC
    - cron: '0 0 * * 0'

permissions:
  contents: read
  issues: write

jobs:
  report:
    runs-on: ubuntu-latest
    steps:
      - name: Generate weekly status
        id: status
        uses: actions/github-script@v6
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const now = new Date();

            // Calculate ISO week start (Monday) and end (Sunday)
            const weekStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
            weekStart.setUTCHours(0, 0, 0, 0);
            const day = weekStart.getUTCDay();
            const diff = (day + 6) % 7; // days since Monday
            weekStart.setUTCDate(weekStart.getUTCDate() - diff);
            const weekEnd = new Date(weekStart);
            weekEnd.setUTCDate(weekStart.getUTCDate() + 6);

            const startStr = weekStart.toISOString().split('T')[0];
            const endStr = weekEnd.toISOString().split('T')[0];

            // Search merged PRs
            const mergedPRs = await github.rest.search.issuesAndPullRequests({
              q: `repo:${owner}/${repo} is:pr is:merged merged:>=${startStr} merged:<=${endStr}`,
              per_page: 100
            });
            const mergedCount = mergedPRs.data.total_count;

            // Search closed issues
            const closedIssues = await github.rest.search.issuesAndPullRequests({
              q: `repo:${owner}/${repo} is:issue is:closed closed:>=${startStr} closed:<=${endStr}`,
              per_page: 100
            });
            const closedCount = closedIssues.data.total_count;

            // Build markdown body
            const body = `
## Weekly Repo Status — ${startStr}–${endStr}

- **Merged PRs**: ${mergedCount}
- **Closed Issues**: ${closedCount}

> *This report was generated automatically by the Weekly Repo Status workflow.*
`;

            // Create a new issue for the status
            const issue = await github.rest.issues.create({
              owner,
              repo,
              title: `Weekly Repo Status — ${startStr}–${endStr}`,
              body
            });

            core.setOutput('issue_number', issue.data.number);
      - name: Label the status issue
        uses: actions/github-script@v6
        with:
          script: |
            const issueNumber = '${{ steps.status.outputs.issue_number }}';
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumber,
              labels: ['weekly-status']
            });
```

